+  message: Extract<import('../../types/messages.js').IncomingMessage, {type: 'list_sessions'}>
+): Promise<void> {
+  if (!history?.enabled) {
+    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
+    return;
+  }
+  if (ws.userId === undefined) {
+    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
+    return;
+  }
+  try {
+    if (!store.listFor) throw new StoreCannotList();
+    const summaries = await store.listFor(ws.userId, {limit: message.limit, before: message.before});
+    sendJson(ws, {
+      type: 'session_list',
+      sessions: summaries.map(summary => ({
+        ...summary,
+        createdAt: summary.createdAt.toISOString(),
+        updatedAt: summary.updatedAt.toISOString(),
+      })),
+    });
+  } catch (error) {
+    const reason = error instanceof Error ? error.message : String(error);
+    const unsupported = error instanceof StoreCannotList;
+    if (!unsupported)
+      log.error('ws', 'conversation list failed', {sessionId: session.sessionId, userId: ws.userId, error: reason});
+    sendError(
+      ws,
+      unsupported ? ErrorCodes.UNSUPPORTED : ErrorCodes.SERVER_ERROR,
+      unsupported ? 'Conversation listing is not supported' : 'Failed to process message'
+    );
+  }
 }

